insert into public.vocabulary_items
(vocabulary_id,term,part_of_speech,core_meaning,senses,word_family,collocations,status)
values
('vocab_distribute','distribute','verb','to give out something to a number of people or places, or to share it among them','[{"senseId":"distribute_1","meaning":"to give out something to a number of people or places, or to share it among them","acceptedParaphrases":["give out to several people","share among a group"],"masteryContexts":[{"contextId":"u7_41_distribute_meaning","text":"The teacher asked two students to distribute the worksheets before the lesson began.","meaning":"to give out to several people","wrongMeanings":["to collect from several people","to keep for herself","to throw away after the lesson"]},{"contextId":"u7_41_distribute_paraphrase","text":"The charity aims to distribute food parcels to families in the nearby villages.","meaning":"to deliver to a number of places","wrongMeanings":["to take from a number of places","to sell at a high price in a few places","to store for a long time in one place"]}],"situationDistractors":["A girl handed one leaflet to each person who entered the hall.","A manager shared the extra tasks out equally among the five workers.","A volunteer delivered food parcels to families in three villages.","The cook added salt to the soup and stirred it slowly.","The coach drove the team to the stadium before the match.","A girl painted a picture of the harbour for her art lesson."],"gapDistractors":[{"contextId":"u7_41_distribute_gap_1","answer":"distribute","wrong":["collect","borrow","repair"]},{"contextId":"u7_41_distribute_gap_2","answer":"distribute","wrong":["forget","invent","decorate"]},{"contextId":"u7_41_distribute_gap_3","answer":"distribute","wrong":["postpone","photograph","celebrate"]}],"spellingErrors":["distrubute","distribut","distrabute","distribuet","disrtibute","distribyute"],"wordFamilyForms":[{"form":"distribute","partOfSpeech":"verb","example":"Volunteers will distribute the leaflets in the town centre on Saturday.","pedagogicallyUseful":true},{"form":"distribution","partOfSpeech":"noun","example":"The distribution of the exam papers began exactly at nine o’clock.","pedagogicallyUseful":true,"altExample":"The fair distribution of work is important for a happy team."},{"form":"distributor","partOfSpeech":"noun","example":"The distributor delivers fresh fruit to more than two hundred shops.","pedagogicallyUseful":true,"altExample":"The book’s distributor promised to send copies to every school in the region."}],"masteryPassages":[{"passageId":"u7_41_distribute_passage_1","contextId":"u7_41_distribute_gap_1","text":"The school was holding a careers evening, and hundreds of programmes had been printed. Two students stood at the door to ____ them to every visitor who arrived.","answer":"distribute"},{"passageId":"u7_41_distribute_passage_2","contextId":"u7_41_distribute_gap_2","text":"The new manager was careful to be fair. She did not give all the difficult tasks to one person but decided to ____ them equally among the whole team.","answer":"distribute"}],"contextDependentParaphrases":[],"wrongParaphrases":["to collect from many people","to keep for yourself","to destroy after using"],"misleadingDistractors":["to collect from a number of people","to keep for yourself","to destroy after use"],"teacherNote":"Verb: to give out something to a number of people or places, or to share it among them (distribute leaflets, distribute the work). It often takes among or to. Boundary: distribute means to give out to many; collect means to take in. The business sense (to supply goods to shops) is related but is not the focus here. Related forms (distribution, distributor) are taught in the Word Family pathway."}]'::jsonb,'["distribution","distributor"]'::jsonb,'["distribute leaflets","distribute fairly","distribute among"]'::jsonb,'live'),
('vocab_allocate','allocate','verb','to give a share of money, time or other resources to a person or purpose','[{"senseId":"allocate_1","meaning":"to give a share of money, time or other resources to a person or purpose","acceptedParaphrases":["give a share of something to","set aside for a particular purpose"],"masteryContexts":[{"contextId":"u7_42_allocate_meaning","text":"The head teacher decided to allocate two hours each week for students to practise interview skills.","meaning":"to set aside a share for a purpose","wrongMeanings":["to take away time from a purpose","to ask for payment for a purpose","to forget the reason for a purpose"]},{"contextId":"u7_42_allocate_paraphrase","text":"The company will allocate each applicant a time for the interview, so nobody has to wait for long.","meaning":"to give a share to each person","wrongMeanings":["to ask a share from each person","to take a share away from each person","to count the shares of each person"]}],"situationDistractors":["A teacher gave each group a set number of minutes to present its project.","A manager set aside part of the budget for training new staff.","A school reserved one classroom every Friday for the debating club.","The conductor raised his arms and the orchestra began to play.","A boy swept the classroom floor after the last lesson of the day.","The farmer drove the tractor across the muddy field."],"gapDistractors":[{"contextId":"u7_42_allocate_gap_1","answer":"allocate","wrong":["borrow","repair","forget"]},{"contextId":"u7_42_allocate_gap_2","answer":"allocate","wrong":["invent","decorate","translate"]},{"contextId":"u7_42_allocate_gap_3","answer":"allocate","wrong":["postpone","photograph","celebrate"]}],"spellingErrors":["alocate","allocat","allokate","alloccate","allicate","allocete"],"masteryPassages":[{"passageId":"u7_42_allocate_passage_1","contextId":"u7_42_allocate_gap_1","text":"The charity had only a small budget for the event. The manager had to ____ the money carefully, so that enough was left for the food, the hall and the posters.","answer":"allocate"},{"passageId":"u7_42_allocate_passage_2","contextId":"u7_42_allocate_gap_2","text":"The head teacher knew that students needed practice with interviews. She agreed to ____ one lesson a week for mock interviews with local business people.","answer":"allocate"}],"contextDependentParaphrases":[],"wrongParaphrases":["to take away a share of","to ask for payment of","to count the total of"],"misleadingDistractors":["to take away a share from","to ask for repayment of","to count the total of"],"teacherNote":"Verb: to give a share of money, time, space or other resources to a person or purpose (allocate money to, allocate time for). Boundary: allocate means an official decision to give a share for a purpose; give is the general word. It is spelled with double l, one c."}]'::jsonb,'[]'::jsonb,'["allocate time","allocate money to","allocate resources"]'::jsonb,'live'),
('vocab_responsible','responsible','adjective','having a duty to do something or take care of it, and able to be trusted to do it well','[{"senseId":"responsible_1","meaning":"having a duty to do something or take care of it, and able to be trusted to do it well","acceptedParaphrases":["having a duty to take care of something","sensible and able to be trusted"],"masteryContexts":[{"contextId":"u7_43_responsible_meaning","text":"In her last job, Rania was responsible for training all the new staff.","meaning":"having the duty to look after something","wrongMeanings":["having the wish to leave something","having the right to ignore something","having the power to change something"]},{"contextId":"u7_43_responsible_paraphrase","text":"The manager looked for a responsible person who could be trusted to lock the building at night.","meaning":"sensible and able to be trusted","wrongMeanings":["forgetful and difficult to find","cheerful and easy to please","quiet and unwilling to speak"]}],"situationDistractors":["A girl was given the keys to the shop and told that she must lock it every evening.","A boy always brought the equipment back and never forgot to switch off the lights.","A woman said that she was in charge of the budget for the whole department.","The librarian stamped each book and put it on the trolley.","A boy tied his shoelaces and then ran to catch the school bus.","Heavy rain fell on the roof of the bus shelter all afternoon."],"gapDistractors":[{"contextId":"u7_43_responsible_gap_1","answer":"responsible","wrong":["frozen","rectangular","wooden"]},{"contextId":"u7_43_responsible_gap_2","answer":"responsible","wrong":["enormous","furious","distant"]},{"contextId":"u7_43_responsible_gap_3","answer":"responsible","wrong":["bitter","crowded","careless"]}],"spellingErrors":["responsable","resposible","responsibel","responcible","resonsible","responcable"],"wordFamilyForms":[{"form":"responsible","partOfSpeech":"adjective","example":"The manager is responsible for the safety of everyone in the building.","pedagogicallyUseful":true},{"form":"responsibility","partOfSpeech":"noun","example":"Looking after the money was a big responsibility for such a young worker.","pedagogicallyUseful":true,"altExample":"The head teacher gave the older students more responsibility for organising the event."},{"form":"irresponsible","partOfSpeech":"adjective","example":"It would be irresponsible to leave young children alone in the room.","pedagogicallyUseful":true,"altExample":"The company described the delay as an irresponsible decision by the managers."}],"masteryPassages":[{"passageId":"u7_43_responsible_passage_1","contextId":"u7_43_responsible_gap_1","text":"The summer camp needed a young person to take charge of the afternoon activities. The organiser did not choose the loudest applicant. She chose Amir, because he seemed calm, sensible and ____.","answer":"responsible"},{"passageId":"u7_43_responsible_passage_2","contextId":"u7_43_responsible_gap_2","text":"In the interview, Mei explained that she had been ____ for training the new volunteers in her last job. The manager could see that she was used to taking duties seriously.","answer":"responsible"}],"contextDependentParaphrases":[],"wrongParaphrases":["wishing to avoid work","able to run quickly","easy to find in a building"],"misleadingDistractors":["wishing to avoid any kind of work","able to run faster than other people","easy to find in a large building"],"teacherNote":"Adjective: having a duty to do or look after something (responsible for), and also sensible and trustworthy (a responsible person). It is often followed by for. Boundary: responsible for means that something is your duty or you caused it; it is different from respond, which is a separate target in this unit. Related forms (responsibility, responsibly, irresponsible) are taught in the Word Family pathway."}]'::jsonb,'["responsibility","irresponsible"]'::jsonb,'["responsible for","a responsible person","a responsible attitude"]'::jsonb,'live'),
('vocab_editor','editor','noun','a person whose job is to check and correct written work before it is published or finished','[{"senseId":"editor_1","meaning":"a person whose job is to check and correct written work before it is published or finished","acceptedParaphrases":["person who corrects writing before it appears","person in charge of what a newspaper prints"],"masteryContexts":[{"contextId":"u7_44_editor_meaning","text":"The editor of the school newspaper corrected the spelling and shortened the longest article.","meaning":"a person who checks and improves writing","wrongMeanings":["a person who delivers the newspapers to shops","a person who draws pictures for newspapers","a person who prints the pages of newspapers"]},{"contextId":"u7_44_editor_paraphrase","text":"As editor of the student magazine, Liam decided which stories would appear on the front page.","meaning":"a person in charge of what is published","wrongMeanings":["a person who sells advertising in a magazine","a person who reads a magazine for pleasure","a person who writes only the weather reports"]}],"situationDistractors":["A woman read through a young writer’s article and changed several sentences to make them clearer.","A student chose which stories would be printed in the school magazine and which would be left out.","A man checked each article for mistakes before the newspaper was sent to the printer.","The cook added salt to the soup and stirred it slowly.","The coach drove the team to the stadium before the match.","A girl painted a picture of the harbour for her art lesson."],"gapDistractors":[{"contextId":"u7_44_editor_gap_1","answer":"editor","wrong":["passenger","harbour","ticket"]},{"contextId":"u7_44_editor_gap_2","answer":"editor","wrong":["recipe","museum","umbrella"]},{"contextId":"u7_44_editor_gap_3","answer":"editor","wrong":["souvenir","carpet","staircase"]}],"spellingErrors":["editer","ediyor","eddiotr","editur","eddittor","editar"],"masteryPassages":[{"passageId":"u7_44_editor_passage_1","contextId":"u7_44_editor_gap_1","text":"Mei wrote an article about her visit to the local factory. The ____ of the school magazine read it, corrected two spelling mistakes and asked her to add a short introduction.","answer":"editor"},{"passageId":"u7_44_editor_passage_2","contextId":"u7_44_editor_gap_2","text":"Few people see the work that happens before an article is printed. A careful ____ checks the facts, removes repeated ideas and makes sure that the sentences are clear.","answer":"editor"}],"contextDependentParaphrases":[],"wrongParaphrases":["person who writes the first draft","person who sells newspapers","person who reads aloud"],"misleadingDistractors":["a person who writes the first draft of a book","a person who prints and sells newspapers","a person who reads aloud for an audience"],"teacherNote":"Noun: a person whose job is to check, correct and improve written work before it is published, or who is in charge of a newspaper or magazine (the editor of the school magazine). Boundary: the editor improves another person’s writing; the writer creates it. The computer sense (a text editor) is not taught here."}]'::jsonb,'[]'::jsonb,'["the editor of","a newspaper editor","the editor’s decision"]'::jsonb,'live'),
('vocab_proofread','proofread','verb','to read a piece of writing carefully in order to find and correct mistakes before it is finished','[{"senseId":"proofread_1","meaning":"to read a piece of writing carefully in order to find and correct mistakes before it is finished","acceptedParaphrases":["read carefully to find mistakes","check writing for errors"],"masteryContexts":[{"contextId":"u7_45_proofread_meaning","text":"Before you send the application, proofread it twice, because a careless mistake could cost you the interview.","meaning":"to read carefully and correct errors","wrongMeanings":["to translate something into another language","to read something aloud to an audience","to write something very quickly"]},{"contextId":"u7_45_proofread_paraphrase","text":"Amir asked his sister to proofread his personal statement and to circle every mistake in grammar.","meaning":"to check writing for small mistakes","wrongMeanings":["to start a piece of writing","to copy writing from a book","to add more ideas to writing"]}],"situationDistractors":["A girl read her essay slowly from the end to the beginning and corrected two spelling mistakes.","A boy asked a friend to look through his cover letter and mark any wrong punctuation.","A teacher read through the questions before the test and found a missing word.","The conductor raised his arms and the orchestra began to play.","A boy swept the classroom floor after the last lesson of the day.","The farmer drove the tractor across the muddy field."],"gapDistractors":[{"contextId":"u7_45_proofread_gap_1","answer":"proofread","wrong":["borrow","repair","forget"]},{"contextId":"u7_45_proofread_gap_2","answer":"proofread","wrong":["invent","decorate","translate"]},{"contextId":"u7_45_proofread_gap_3","answer":"proofread","wrong":["postpone","photograph","celebrate"]}],"spellingErrors":["proofred","proffread","proof-read","prufread","proofreed","proofrede"],"masteryPassages":[{"passageId":"u7_45_proofread_passage_1","contextId":"u7_45_proofread_gap_1","text":"Hasan wrote his cover letter in one evening and sent it the next morning without looking at it again. The employer noticed three spelling mistakes, and Hasan wished he had taken ten minutes to ____ the letter.","answer":"proofread"},{"passageId":"u7_45_proofread_passage_2","contextId":"u7_45_proofread_gap_2","text":"A professional writer never sends a final copy before checking it. She reads the text slowly, one line at a time, to ____ it for spelling, grammar and punctuation.","answer":"proofread"}],"contextDependentParaphrases":[],"wrongParaphrases":["to read aloud to listeners","to write without planning","to translate into another language"],"misleadingDistractors":["to read aloud to a group of listeners","to write a long text without any planning","to translate a text into another language"],"teacherNote":"Verb: to read a piece of writing carefully to find and correct mistakes in spelling, grammar and punctuation before it is finished or sent. It is one word. The past tense is spelled the same way (proofread). Boundary: proofreading corrects small errors; editing may change the content or structure."}]'::jsonb,'[]'::jsonb,'["proofread carefully","proofread your work","proofread twice"]'::jsonb,'live'),
('vocab_layout','layout','noun','the way in which text, pictures and other items are arranged on a page or screen','[{"senseId":"layout_1","meaning":"the way in which text, pictures and other items are arranged on a page or screen","acceptedParaphrases":["arrangement of items on a page","way a page is organised visually"],"masteryContexts":[{"contextId":"u7_46_layout_meaning","text":"The designer changed the layout of the poster so that the date was easier to see.","meaning":"the way items are arranged on a page","wrongMeanings":["the main message of a poster","the price of printing a poster","the person who reads a poster"]},{"contextId":"u7_46_layout_paraphrase","text":"A simple layout with plenty of white space makes a CV look neat and professional.","meaning":"an arrangement of text and images on a page","wrongMeanings":["a set of rules for writing a page","a short summary of a page","a correction made to a page"]}],"situationDistractors":["A student moved the headings and the photograph on her poster so that the page looked tidier.","A designer put the title at the top, the picture in the middle and the contact details at the bottom.","A boy changed the margins and spacing on his CV so that it fitted on one page.","The cook added salt to the soup and stirred it slowly.","The coach drove the team to the stadium before the match.","A girl painted a picture of the harbour for her art lesson."],"gapDistractors":[{"contextId":"u7_46_layout_gap_1","answer":"layout","wrong":["recipe","harbour","ticket"]},{"contextId":"u7_46_layout_gap_2","answer":"layout","wrong":["neighbour","umbrella","museum"]},{"contextId":"u7_46_layout_gap_3","answer":"layout","wrong":["souvenir","carpet","staircase"]}],"spellingErrors":["layoute","laiout","lay-out","layot","laylout","layuot"],"masteryPassages":[{"passageId":"u7_46_layout_passage_1","contextId":"u7_46_layout_gap_1","text":"The two CVs contained almost exactly the same information. The first, however, was crowded and confusing, while the second had a clear ____ with headings and white space, so the manager read it first.","answer":"layout"},{"passageId":"u7_46_layout_passage_2","contextId":"u7_46_layout_gap_2","text":"Before printing the school poster, the students tried three different designs. They finally chose the one with a bold title at the top, a large picture in the middle and a simple ____ that made the date easy to find.","answer":"layout"}],"contextDependentParaphrases":[],"wrongParaphrases":["main idea of a text","total number of pages","list of people who read a text"],"misleadingDistractors":["the main idea of a piece of writing","the total number of pages in a book","a list of the people who have read a text"],"teacherNote":"Noun: the way in which text, pictures and other items are arranged on a page or screen (the layout of a CV, a clear layout). It is written as one word. Boundary: layout is about where things are placed on the page; format (also a target in this unit) is the wider way something is organised or presented. It also describes the plan of a room or a building."}]'::jsonb,'[]'::jsonb,'["a clear layout","the layout of a page","change the layout"]'::jsonb,'live'),
('vocab_visual','visual','adjective','connected with seeing, or using pictures, images and other things that can be seen','[{"senseId":"visual_1","meaning":"connected with seeing, or using pictures, images and other things that can be seen","acceptedParaphrases":["connected with seeing","using pictures and images"],"masteryContexts":[{"contextId":"u7_47_visual_meaning","text":"The teacher used a visual timeline to help the students understand the order of events.","meaning":"using images that can be seen","wrongMeanings":["using sounds that can be heard","using words that can be spoken","using objects that can be touched"]},{"contextId":"u7_47_visual_paraphrase","text":"Many people are visual learners and remember information better when they see it in a picture.","meaning":"connected with seeing","wrongMeanings":["connected with hearing","connected with reading aloud","connected with writing by hand"]}],"situationDistractors":["A student used a colourful chart and two photographs to explain her project.","A teacher drew a diagram on the board to show how the parts of the machine fitted together.","A speaker showed a short film instead of reading a long text.","The librarian stamped each book and put it on the trolley.","A boy tied his shoelaces and then ran to catch the school bus.","Heavy rain fell on the roof of the bus shelter all afternoon."],"gapDistractors":[{"contextId":"u7_47_visual_gap_1","answer":"visual","wrong":["frozen","rectangular","wooden"]},{"contextId":"u7_47_visual_gap_2","answer":"visual","wrong":["enormous","furious","distant"]},{"contextId":"u7_47_visual_gap_3","answer":"visual","wrong":["bitter","crowded","careless"]}],"spellingErrors":["visaul","vissual","visuel","visuall","visal","viscual"],"wordFamilyForms":[{"form":"visual","partOfSpeech":"adjective","example":"A visual summary of the data helped the committee to understand the problem quickly.","pedagogicallyUseful":true},{"form":"visually","partOfSpeech":"adverb","example":"The poster was visually attractive, with a bold title and a clear picture.","pedagogicallyUseful":true,"altExample":"The two posters were visually very different, although they contained the same facts."},{"form":"visualise","partOfSpeech":"verb","example":"It helps to visualise yourself giving a calm answer before the interview.","pedagogicallyUseful":true,"altExample":"Try to visualise the room, the panel and your own calm voice before you go in."}],"masteryPassages":[{"passageId":"u7_47_visual_passage_1","contextId":"u7_47_visual_gap_1","text":"The first speaker read from a long page of notes and did not look up. The second speaker used a simple ____ aid: a large photograph that showed exactly what she was describing. The audience remembered her talk much better.","answer":"visual"},{"passageId":"u7_47_visual_passage_2","contextId":"u7_47_visual_gap_2","text":"Some students learn better when they see information in pictures and charts. These ____ learners often use colours and diagrams to help them revise.","answer":"visual"}],"contextDependentParaphrases":[],"wrongParaphrases":["connected with hearing","connected with writing","connected with touching"],"misleadingDistractors":["connected with hearing","connected with writing","connected with touching"],"teacherNote":"Adjective: connected with seeing, or using pictures, diagrams and other things that can be seen (a visual aid, visual information). Boundary: visual is about what can be seen; it is not the same as visible, which means able to be seen. Related forms (visually, visualise) are taught in the Word Family pathway."}]'::jsonb,'["visually","visualise"]'::jsonb,'["a visual aid","visual information","a visual learner"]'::jsonb,'live'),
('vocab_criteria_7','criteria','noun','the standards or points that are used to judge or decide something, such as which candidate to choose','[{"senseId":"criteria_7_1","meaning":"the standards or points that are used to judge or decide something, such as which candidate to choose","acceptedParaphrases":["standards used for judging","points used to decide"],"masteryContexts":[{"contextId":"u7_48_criteria_7_meaning","text":"The panel used five criteria to decide which candidate should receive the scholarship.","meaning":"the standards used to judge something","wrongMeanings":["the people who apply for something","the rewards given after a decision","the mistakes found in a decision"]},{"contextId":"u7_48_criteria_7_paraphrase","text":"Before the task, the teacher gave the class the assessment criteria so they knew exactly how to earn high marks.","meaning":"the points used to decide marks","wrongMeanings":["the questions answered by the class","the answers given in a test","the times set for a task"]}],"situationDistractors":["A teacher handed out a sheet that listed what the examiners would look for in a good speech.","A panel agreed that each candidate would be judged on skills, experience and attitude.","A judge told the contestants exactly how the winner would be chosen.","The cook added salt to the soup and stirred it slowly.","The coach drove the team to the stadium before the match.","A girl painted a picture of the harbour for her art lesson."],"gapDistractors":[{"contextId":"u7_48_criteria_7_gap_1","answer":"criteria","wrong":["recipes","harbours","tickets"]},{"contextId":"u7_48_criteria_7_gap_2","answer":"criteria","wrong":["neighbours","umbrellas","museums"]},{"contextId":"u7_48_criteria_7_gap_3","answer":"criteria","wrong":["souvenirs","carpets","staircases"]}],"spellingErrors":["criterea","critiria","criteriea","cryteria","critera","criterria"],"masteryPassages":[{"passageId":"u7_48_criteria_7_passage_1","contextId":"u7_48_criteria_7_gap_1","text":"Nobody on the panel wanted to make an unfair decision. They agreed on four clear ____ before they read any applications: relevant experience, communication skills, teamwork and punctuality.","answer":"criteria"},{"passageId":"u7_48_criteria_7_passage_2","contextId":"u7_48_criteria_7_gap_2","text":"The teacher gave the students a sheet showing the ____ for the speaking test. It listed clarity, accuracy, range of vocabulary and confidence, so that everyone knew what the examiner was looking for.","answer":"criteria"}],"contextDependentParaphrases":[],"wrongParaphrases":["names of the people taking part","prizes given to winners","questions asked at the end"],"misleadingDistractors":["the names of the people who take part","the prizes that are given to winners","the questions that are asked at the end"],"teacherNote":"Unit 7 item (criteria_7), separate from the Unit 1 criteria item; it shares only the lexical spelling list. Sense in this unit: the standards or points used to judge candidates or work. Criteria is plural and takes a plural verb (the criteria are); the singular criterion is not taught here. Boundary: criteria are what you measure against, so candidates are judged by them, not the other way round."}]'::jsonb,'[]'::jsonb,'["assessment criteria","meet the criteria","selection criteria"]'::jsonb,'live'),
('vocab_accurate','accurate','adjective','correct and exact, without any mistakes','[{"senseId":"accurate_1","meaning":"correct and exact, without any mistakes","acceptedParaphrases":["correct and exact","free from mistakes"],"masteryContexts":[{"contextId":"u7_49_accurate_meaning","text":"The examiner praised her accurate description of the graph, which included every figure correctly.","meaning":"correct and exact","wrongMeanings":["neat and attractive","long and detailed","quick and careless"]},{"contextId":"u7_49_accurate_paraphrase","text":"It is important to give accurate dates and names when you fill in an application form.","meaning":"free from mistakes","wrongMeanings":["written in an attractive way","copied from another form","completed after the closing date"]}],"situationDistractors":["A girl checked every date and name on her form twice and found them all correct.","A boy measured the table carefully and wrote down the exact length.","A reporter checked each fact with two different sources before the story was printed.","The librarian stamped each book and put it on the trolley.","A boy tied his shoelaces and then ran to catch the school bus.","Heavy rain fell on the roof of the bus shelter all afternoon."],"gapDistractors":[{"contextId":"u7_49_accurate_gap_1","answer":"accurate","wrong":["frozen","rectangular","wooden"]},{"contextId":"u7_49_accurate_gap_2","answer":"accurate","wrong":["enormous","furious","distant"]},{"contextId":"u7_49_accurate_gap_3","answer":"accurate","wrong":["bitter","crowded","careless"]}],"spellingErrors":["acurate","accurat","accuret","acccurate","accurete","akurate"],"wordFamilyForms":[{"form":"accurate","partOfSpeech":"adjective","example":"The report gave an accurate account of what had happened at the meeting.","pedagogicallyUseful":true},{"form":"accuracy","partOfSpeech":"noun","example":"The accuracy of the figures is more important than the speed of the report.","pedagogicallyUseful":true,"altExample":"The teacher checked the accuracy of every spelling in the final essay."},{"form":"accurately","partOfSpeech":"adverb","example":"She described the diagram accurately and did not miss a single detail.","pedagogicallyUseful":true,"altExample":"The machine can measure small distances accurately, even in poor light."}],"masteryPassages":[{"passageId":"u7_49_accurate_passage_1","contextId":"u7_49_accurate_gap_1","text":"The newspaper printed a correction the next day. The first report had said that two hundred people attended the fair, but the real number was only eighty. The editor reminded the writers that every article must be ____.","answer":"accurate"},{"passageId":"u7_49_accurate_passage_2","contextId":"u7_49_accurate_gap_2","text":"The examiner told the class that a good description of a graph does not have to be long. It must be ____, with correct figures and no guesses.","answer":"accurate"}],"contextDependentParaphrases":[],"wrongParaphrases":["written in a neat style","quick to produce but unchecked","long and full of detail"],"misleadingDistractors":["written in a very neat style","quick to produce but not checked","long and full of extra detail"],"teacherNote":"Adjective: correct and exact, with no mistakes (accurate information, an accurate description). Boundary: accurate is about being correct and exact; it is not the same as honest, because a person can be honest but make a mistake. In writing it describes facts, numbers and spelling. Related forms (accuracy, accurately, inaccurate) are taught in the Word Family pathway."}]'::jsonb,'["accuracy","accurately"]'::jsonb,'["accurate information","an accurate description","accurate to"]'::jsonb,'live'),
('vocab_punctuation','punctuation','noun','the marks, such as full stops, commas and question marks, that are used in writing to make the meaning clear','[{"senseId":"punctuation_1","meaning":"the marks, such as full stops, commas and question marks, that are used in writing to make the meaning clear","acceptedParaphrases":["marks that make writing clear","full stops, commas and similar signs"],"masteryContexts":[{"contextId":"u7_50_punctuation_meaning","text":"Careful punctuation can change the meaning of a sentence completely, so check it before you send an application.","meaning":"the marks used to make writing clear","wrongMeanings":["the spelling of difficult words","the speed at which people read","the order of paragraphs in a text"]},{"contextId":"u7_50_punctuation_paraphrase","text":"The teacher circled the mistakes in grammar and punctuation and asked the students to correct them.","meaning":"full stops, commas and similar marks","wrongMeanings":["words that are spelt in the wrong way","pages that are written without a title","sentences that are copied from a book"]}],"situationDistractors":["A student read his letter aloud and added commas wherever he paused for a breath.","A girl added a question mark at the end of her last sentence and checked the apostrophes.","A teacher circled the missing full stops in a student’s essay.","The cook added salt to the soup and stirred it slowly.","The coach drove the team to the stadium before the match.","A girl painted a picture of the harbour for her art lesson."],"gapDistractors":[{"contextId":"u7_50_punctuation_gap_1","answer":"punctuation","wrong":["recipe","harbour","ticket"]},{"contextId":"u7_50_punctuation_gap_2","answer":"punctuation","wrong":["neighbour","umbrella","museum"]},{"contextId":"u7_50_punctuation_gap_3","answer":"punctuation","wrong":["souvenir","carpet","staircase"]}],"spellingErrors":["punctuaton","punctuashun","punctation","punktuation","punctuasion","punctuatian"],"masteryPassages":[{"passageId":"u7_50_punctuation_passage_1","contextId":"u7_50_punctuation_gap_1","text":"The sentence “Let’s eat, Grandma” and the sentence “Let’s eat Grandma” look almost the same, but the ____ changes the meaning completely. A small comma can make a very big difference.","answer":"punctuation"},{"passageId":"u7_50_punctuation_passage_2","contextId":"u7_50_punctuation_gap_2","text":"Before she sent the application, Nour read it through and corrected the spelling. Then she checked the full stops and commas, because poor ____ can make a letter seem careless.","answer":"punctuation"}],"contextDependentParaphrases":[],"wrongParaphrases":["spelling of difficult words","shape of handwritten letters","order of paragraphs"],"misleadingDistractors":["the correct spelling of difficult words","the neat shape of handwritten letters","the order in which paragraphs are arranged"],"teacherNote":"Noun: the marks, such as full stops, commas, question marks and apostrophes, used in writing to make the meaning clear. It is uncountable. Boundary: punctuation is about the marks between words and sentences; spelling is about the letters inside words. The verb punctuate is not taught here."}]'::jsonb,'[]'::jsonb,'["correct punctuation","spelling and punctuation","check the punctuation"]'::jsonb,'live')
